import {APPAREL_COLOURS} from '/apparel-colours.mjs';
const image=src=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});
const colour=(p,c)=>APPAREL_COLOURS[p.id]?.[Number(c)]||'#ffffff';
const asset=(side,part='')=>`/studio/garments/shirt-${side===1?'back':'front'}${part}.png`;
function illustration(p,c){const tote=p.garment?.category==='totes',tank=p.garment?.category==='tanks',hat=p.garment?.group==='hats',hood=/hood/i.test(p.name),polo=/polo/i.test(p.name),long=/long|sweat|hood|jacket/i.test(p.name);return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="1000" viewBox="0 0 1000 1000"><defs><linearGradient id="fabric"><stop stop-color="${c}"/><stop offset=".5" stop-color="${c}"/><stop offset="1" stop-color="#999" stop-opacity=".35"/></linearGradient></defs><g fill="url(#fabric)" stroke="#888" stroke-opacity=".4" stroke-width="3">${tote?'<path d="M300 350H700L750 870H250Z"/><path d="M380 350V230Q500 100 620 230V350" fill="none" stroke-width="45"/>':tank?'<path d="M360 150H420Q500 280 580 150H640L620 310L690 870H310L380 310Z"/>':hat?'<path d="M280 570Q260 290 500 290Q740 290 720 570Z"/><path d="M280 570Q510 530 800 650Q540 760 250 650Z"/>':`<path d="M400 150Q500 195 600 150L730 210L${long?'895 700L790 755L680 390':'860 390L730 450L680 340'}L690 870Q500 895 310 870L320 340L${long?'210 755L105 700':'270 450L140 390'}L270 210Z"/>${hood?'<path d="M400 150Q360 25 500 30Q640 25 600 150L550 200L450 200Z"/><path d="M400 680H600L630 790H370Z"/>':polo?'<path d="M400 150L460 250L500 190L540 250L600 150"/><path d="M500 190V360"/>':'<path d="M400 150Q500 245 600 150" fill="none"/>'}`}</g></svg>`;}
export function garmentPreview(p,c,side){const col=colour(p,c);if(p.garment?.category==='t-shirts')return `<div class="garment-visual" style="--garment-colour:${col};--garment-mask:url('${asset(side,'-mask')}')"><div class="garment-colour-mask"></div><img class="garment-texture" src="${asset(side,'-texture')}" alt="Blank ${side===1?'back':'front'} of T-shirt without a model"></div>`;return `<img class="garment-visual" style="width:100%;height:100%" src="data:image/svg+xml,${encodeURIComponent(illustration(p,col))}" alt="Blank garment illustration without a model">`;}
export async function garmentPreviewImage(p,c,side){if(p.garment?.category!=='t-shirts')return image('data:image/svg+xml,'+encodeURIComponent(illustration(p,colour(p,c))));const [mask,texture]=await Promise.all([image(asset(side,'-mask')),image(asset(side,'-texture'))]);const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1000;const ctx=canvas.getContext('2d');ctx.drawImage(mask,0,0,1000,1000);ctx.globalCompositeOperation='source-in';ctx.fillStyle=colour(p,c);ctx.fillRect(0,0,1000,1000);ctx.globalCompositeOperation='source-over';ctx.drawImage(texture,0,0,1000,1000);return canvas;}
